'use client';
import { useState } from 'react';
import { getSupabase } from '../../../lib/supabase';
export default function SignalsManager() {
  const [form, setForm] = useState({ asset: '', direction: 'BUY', entry_price: '', take_profit: '', stop_loss: '', is_vip_only: false });
  const [status, setStatus] = useState('');
  async function submit(e: React.FormEvent) { e.preventDefault(); setStatus('Publishing…'); try { const supabase = getSupabase(); if (!supabase) throw new Error('Supabase is not configured.'); const { error } = await supabase.from('ai_signals').insert({ ...form, entry_price: Number(form.entry_price), take_profit: Number(form.take_profit), stop_loss: Number(form.stop_loss) }); if (error) throw error; setStatus('Signal published successfully.'); setForm({ asset: '', direction: 'BUY', entry_price: '', take_profit: '', stop_loss: '', is_vip_only: false }); } catch (error) { setStatus(error instanceof Error ? error.message : 'Unable to publish signal.'); } }
  return <div className="p-5 md:p-8 lg:p-10"><p className="text-xs font-bold uppercase tracking-[.25em] text-cyan">Market operations</p><h1 className="mt-3 text-3xl font-black">AI Signals</h1><form onSubmit={submit} className="mt-8 max-w-2xl rounded-2xl border border-white/10 bg-card p-6"><h2 className="font-bold">Broadcast a signal</h2><div className="mt-5 grid gap-4"><input required value={form.asset} onChange={e => setForm({ ...form, asset: e.target.value })} className="rounded-xl border border-white/10 bg-ink p-3" placeholder="Asset e.g. EURUSD" /><select value={form.direction} onChange={e => setForm({ ...form, direction: e.target.value })} className="rounded-xl border border-white/10 bg-ink p-3"><option>BUY</option><option>SELL</option></select><div className="grid grid-cols-3 gap-3">{(['entry_price', 'take_profit', 'stop_loss'] as const).map(k => <input required key={k} type="number" step="any" value={form[k]} onChange={e => setForm({ ...form, [k]: e.target.value })} className="rounded-xl border border-white/10 bg-ink p-3" placeholder={k.replace('_', ' ')} />)}</div><label className="flex items-center gap-3 text-sm text-muted"><input type="checkbox" checked={form.is_vip_only} onChange={e => setForm({ ...form, is_vip_only: e.target.checked })} /> VIP-only signal</label><button className="rounded-xl bg-cyan py-3 font-bold text-ink">Publish signal</button>{status && <p className="text-sm text-cyan">{status}</p>}</div></form></div>;
}